void NativeZingo::registerModule(jsi::Runtime &rt, std::shared_ptr<react::CallInvoker> callInvoker) {
    auto invoker = std::make_shared<uniffi_runtime::UniffiCallInvoker>(callInvoker);
    auto tm = std::make_shared<NativeZingo>(rt, invoker);
    auto obj = rt.global().createFromHostObject(rt, tm);
    rt.global().setProperty(rt, "NativeZingo", obj);
}

void NativeZingo::unregisterModule(jsi::Runtime &rt) {
    uniffi::zingo::registry::clearRegistry();
}

jsi::Value NativeZingo::get(jsi::Runtime& rt, const jsi::PropNameID& name) {
    try {
        return jsi::Value(rt, props.at(name.utf8(rt)));
    }
    catch (std::out_of_range &e) {
        return jsi::Value::undefined();
    }
}

std::vector<jsi::PropNameID> NativeZingo::getPropertyNames(jsi::Runtime& rt) {
    std::vector<jsi::PropNameID> rval;
    for (auto& [key, value] : props) {
        rval.push_back(jsi::PropNameID::forUtf8(rt, key));
    }
    return rval;
}

void NativeZingo::set(jsi::Runtime& rt, const jsi::PropNameID& name, const jsi::Value& value) {
    props.insert_or_assign(name.utf8(rt), &value);
}

NativeZingo::~NativeZingo() {
    // Cleanup for callback function RustFutureContinuationCallback
uniffi::zingo::cb::rustfuturecontinuationcallback::cleanup();
    // Cleanup for "free" callback function CallbackInterfaceFree
uniffi::zingo::st::foreignfuture::foreignfuture::free::cleanup();
}

